MCP tool to approve a spec (move it from pending/ to approved/) so Ralph Loop can run it. This closes the human-in-the-loop gap — reviewers can approve specs from Claude Code without touching the filesystem.

Add to server.ts:
```typescript
server.tool(
  'rorca_approve_spec',
  'Approve a pending spec and move it to the approved queue. Once approved, the spec can be executed by Ralph Loop via run-loop.sh. Use rorca_list_specs to find the spec ID first.',
  {
    workspaceId: z.string().describe('Rorca workspace ID'),
    specId: z.string().describe('Spec ID (from rorca_list_specs output)'),
    notes: z.string().optional().describe('Optional approval notes to append to the spec'),
  },
  async ({ workspaceId, specId, notes }) => {
    const res = await fetch(`${RORCA_API}/api/specs/${specId}/approve`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ workspaceId, notes }),
    });
    if (!res.ok) {
      const err = await res.text();
      throw new Error(`Approval failed (${res.status}): ${err}`);
    }
    const { path: approvedPath } = await res.json() as { path: string };
    return {
      content: [{
        type: 'text',
        text: `Spec approved and moved to: ${approvedPath}\n\nRun it with:\n  ./scripts/ralph/run-loop.sh --json ${approvedPath}`
      }]
    };
  }
);
```

