MCP tool to check active pipeline status. Returns the current run's status, how many stories have passed/failed/are pending, and the last log line. Useful for monitoring a running Ralph Loop from Claude Code.

Add to server.ts:
```typescript
server.tool(
  'rorca_pipeline_status',
  'Get the status of the active (or most recent) pipeline run for a workspace. Returns run status (running/paused/done/failed), story-level progress (pass/fail/skip counts), elapsed time, and last log line. Use this to monitor a Ralph Loop session without switching windows.',
  {
    workspaceId: z.string().describe('Rorca workspace ID'),
    runId: z.number().optional().describe('Specific run ID. If omitted, returns the most recent run.'),
  },
  async ({ workspaceId, runId }) => {
    const url = runId
      ? `${RORCA_API}/api/pipeline-runs/${runId}`
      : `${RORCA_API}/api/pipeline-runs?workspaceId=${workspaceId}&limit=1`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`Failed to get pipeline status: ${res.status}`);
    const data = await res.json() as {
      id: number; status: string; specPath: string;
      startedAt: string; finishedAt?: string;
      stories: Array<{ storyId: string; status: string; retries: number }>;
    };
    const run = Array.isArray(data) ? data[0] : data;
    if (!run) return { content: [{ type: 'text', text: `No pipeline runs found for workspace ${workspaceId}` }] };
    const pass = run.stories.filter(s => s.status === 'pass').length;
    const fail = run.stories.filter(s => s.status === 'fail').length;
    const skip = run.stories.filter(s => s.status === 'skip').length;
    const total = run.stories.length;
    const elapsed = run.finishedAt
      ? `${Math.round((new Date(run.finishedAt).getTime() - new Date(run.startedAt).getTime()) / 60000)}m`
      : `${Math.round((Date.now() - new Date(run.startedAt).getTime()) / 60000)}m (running)`;
    const summary = [
      `Run #${run.id}: ${run.status.toUpperCase()} (${elapsed})`,
      `Spec: ${run.specPath}`,
      `Stories: ${pass} pass / ${fail} fail / ${skip} skip / ${total} total`,
    ].join('\n');
    return { content: [{ type: 'text', text: summary }] };
  }
);
```

