Integration test that starts the MCP server as a subprocess, connects via stdio, lists tools, and verifies all 5 tools are registered. Also write the setup instructions to README.md.

File: backend/src/mcp/__tests__/integration.test.ts
```typescript
import { spawn } from 'child_process';
import * as path from 'path';

describe('MCP server integration', () => {
  it('lists all 5 expected tools', (done) => {
    const proc = spawn('npx', ['tsx', path.resolve(__dirname, '../../mcp/server.ts')], {
      env: { ...process.env, DB_PATH: ':memory:', RORCA_API_URL: 'http://localhost:3030' },
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    // Send MCP initialize + tools/list request
    const initialize = JSON.stringify({
      jsonrpc: '2.0', id: 1, method: 'initialize',
      params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'test', version: '1' } }
    });
    const listTools = JSON.stringify({ jsonrpc: '2.0', id: 2, method: 'tools/list', params: {} });
    proc.stdin.write(initialize + '\n');
    proc.stdin.write(listTools + '\n');
    let output = '';
    proc.stdout.on('data', (chunk: Buffer) => { output += chunk.toString(); });
    setTimeout(() => {
      proc.kill();
      const lines = output.trim().split('\n').filter(Boolean);
      const toolsResponse = lines.map(l => { try { return JSON.parse(l); } catch { return null; } })
        .find(r => r?.id === 2);
      expect(toolsResponse).toBeTruthy();
      const toolNames = toolsResponse.result.tools.map((t: { name: string }) => t.name);
      expect(toolNames).toContain('rorca_get_context');
      expect(toolNames).toContain('rorca_generate_spec');
      expect(toolNames).toContain('rorca_list_specs');
      expect(toolNames).toContain('rorca_approve_spec');
      expect(toolNames).toContain('rorca_pipeline_status');
      done();
    }, 3000);
  }, 10000);
});
```

Update ~/rorca/README.md — append section:
```markdown
## MCP Setup (Claude Code)

Add Rorca as an MCP server in Claude Code:

```bash
# From any project directory:
claude mcp add rorca -- npx tsx /path/to/rorca/backend/src/mcp/server.ts
```

Set environment variables in ~/.claude/mcp-servers.json or via:
```bash
claude mcp add rorca -e RORCA_API_URL=http://localhost:3030 \
  -- npx tsx /path/to/rorca/backend/src/mcp/server.ts
```

### Available Tools
- **rorca_get_context** — inject full Direction Stack into current session
- **rorca_generate_spec** — generate a spec JSON from a brief
- **rorca_list_specs** — list pending/approved specs
- **rorca_approve_spec** — approve a pending spec for execution
- **rorca_pipeline_status** — check active pipeline progress
```

